import inspect
from functools import partial

class A:
    def __call__(self):
        pass

print(f"isclass(A): {inspect.isclass(A)}")
print(f"isclass(partial(A)): {inspect.isclass(partial(A))}")
def _impartial(func):
    while isinstance(func, partial):
        func = func.func
    return func
print(f"isclass(_impartial(partial(A))): {inspect.isclass(_impartial(partial(A)))}")

